INSERT INTO `services` (`id`, `name`, `description`, `price`, `payment_type`, `image`, `created_at`, `updated_at`) VALUES
(1, 'Haircut', 'Some popular women’s haircut styles are:\r\n\r\nLong layers: Adds movement and volume while keeping hair long.\r\nBob cut: A short-to-medium haircut, usually around chin or shoulder length.\r\nLob (long bob): Slightly longer than a bob and easy to maintain.\r\nCurtain bangs: Soft front bangs that frame the face nicely.\r\nStep cut: Hair is cut in different levels to create shape and bounce.\r\nU-cut or V-cut: Popular for long hair to create a stylish back shape.\r\nWolf cut: Trendy layered style with more volume on top.\r\nPixie cut: Very short and bold haircut.\r\nStraight cut: Hair is cut evenly at one length for a clean look.\r\n\r\nTypical salon timing:\r\n\r\nBasic trim: 15–20 minutes\r\nLayer cut: 30–45 minutes\r\nBob or lob cut: 30–40 minutes\r\nPixie cut: 30–45 minutes\r\nHaircut with wash and styling: 45–60 minutes\r\n\r\nThe best haircut depends on face shape, hair thickness, and how much styling time someone wants every day.', 500, 'postpaid', 'services/LLcjgUjJVXC2uXg0LxMo3MHJnw3kAzCyDbc4ezfH.jpg', '2026-02-27 00:48:14', '2026-04-08 05:35:16'),
(3, 'Nomal Makcup', 'A normal everyday makeup look for women is usually light, natural, and quick. It is meant to enhance the face without looking too heavy.\r\n\r\nTypical steps:\r\n\r\nClean face – 2 minutes\r\nMoisturizer and sunscreen – 2 minutes\r\nPrimer (optional) – 1 minute\r\nFoundation or BB cream – 3 minutes\r\nConcealer – 2 minutes\r\nCompact powder – 1 minute\r\nEyebrows – 2 minutes\r\nKajal or eyeliner – 2 minutes\r\nMascara – 1 minute\r\nBlush – 1 minute\r\nLipstick or lip balm – 1 minute\r\n\r\nTotal timing is usually around 15 to 20 minutes for a simple daily makeup look.\r\n\r\nFor a very basic quick look, many women just use moisturizer, compact powder, kajal, and lipstick, which can be done in about 5 to 7 minutes.', 1500, 'postpaid', 'services/IiH66bN4tUQJxkWdeFr6GqdM7jiGpJcZEKrcYPuS.jpg', '2026-04-08 05:34:29', '2026-04-08 05:34:29'),
(4, 'Bridal makeup', 'Bridal makeup is heavier and more detailed than normal makeup because it needs to look good in photos, videos, and last for many hours.\r\n\r\nTypical bridal makeup steps:\r\n\r\nFace cleaning and moisturizing – 10 minutes\r\nPrimer – 5 minutes\r\nFoundation and concealer – 15 minutes\r\nContouring and compact powder – 10 minutes\r\nEye makeup, eyeshadow, eyeliner, kajal, lashes – 20 to 30 minutes\r\nEyebrows – 5 minutes\r\nBlush and highlighter – 5 minutes\r\nLip liner and lipstick – 5 minutes\r\nSetting spray and finishing touches – 5 minutes\r\nHair styling, jewelry setting, dupatta or veil setting – 30 to 60 minutes\r\n\r\nTotal timing:\r\n\r\nSimple bridal makeup: 1.5 to 2 hours\r\nFull bridal makeup with hairstyle and dressing: 2.5 to 4 hours\r\n\r\nCommon bridal makeup types:\r\n\r\nNatural bridal makeup\r\nHD makeup\r\nAirbrush makeup\r\nMatte makeup\r\nDewy/glow makeup\r\nTraditional bridal makeup\r\nReception party glam makeup', 5000, 'postpaid', 'services/MPp8eReLRI9kSwvRw2TuOAMVezZ0yHQOINMXtF6q.jpg', '2026-04-08 05:37:07', '2026-04-08 05:37:07'),
(5, 'Man Haircut', 'Popular men’s haircut styles include:\r\n\r\nFade cut: Hair becomes shorter on the sides and back.\r\nUndercut: Short sides with longer hair on top.\r\nCrew cut: Short, clean, and easy to maintain.\r\nBuzz cut: Very short all around.\r\nSide part: Classic style with a neat side line.\r\nPompadour: Longer hair on top with volume.\r\nTextured crop: Short haircut with a modern messy look.\r\nQuiff: Similar to pompadour but more casual.\r\nTaper cut: Gradual shortening around the neck and ears.\r\nFrench crop: Short sides with a small fringe in front.\r\n\r\nTypical salon timing:\r\n\r\nBasic trim: 15–20 minutes\r\nFade cut: 25–40 minutes\r\nCrew cut or buzz cut: 10–20 minutes\r\nUndercut or pompadour: 30–45 minutes\r\nHaircut with beard trim and styling: 45–60 minutes\r\n\r\nHaircuts like fade, crew cut, and textured crop are popular because they look neat and do not need much daily styling.', 250, 'postpaid', 'services/tXb6qdvoMSXOGtHT6Jjl9enaT5paassFXEm054ET.jpg', '2026-04-08 05:38:01', '2026-04-08 05:38:01'),
(6, 'Men’s Beard', 'Popular men’s beard styles include:\r\n\r\nClean shave: No beard, simple and neat.\r\nStubble beard: Very short beard, easy to maintain.\r\nShort boxed beard: Trimmed beard with clean edges.\r\nFull beard: Thick beard covering cheeks and chin.\r\nFrench beard: Beard only around chin and moustache area.\r\nGoatee: Beard mainly on chin.\r\nVan Dyke beard: Pointed beard with moustache.\r\nCorporate beard: Neat and professional-looking beard.\r\nFade beard: Beard blended smoothly into haircut.\r\nDucktail beard: Full beard with pointed chin shape.\r\n\r\nTypical salon timing:\r\n\r\nBeard trim: 10–15 minutes\r\nBeard shaping: 15–25 minutes\r\nFull beard styling: 20–30 minutes\r\nHaircut with beard styling: 45–60 minutes\r\n\r\nShort boxed beard, stubble, and fade beard are very popular because they suit most face shapes and are easy to manage.', 150, 'postpaid', 'services/tZYlV8sy5gDEx9mIsfgxbbggK0FjwGFW2hm4f5Gd.jpg', '2026-04-08 05:38:56', '2026-04-08 05:38:56'),
(7, 'Global hair color', 'Global hair color means coloring all the hair in one shade from top to bottom.\r\n\r\nPopular global hair colors for women:\r\n\r\nNatural black\r\nDark brown\r\nChocolate brown\r\nCaramel brown\r\nBurgundy\r\nWine red\r\nGolden brown\r\nCopper brown\r\nAsh brown\r\nBlonde highlights with global color\r\n\r\nTypical salon timing:\r\n\r\nShort hair: 1 to 1.5 hours\r\nMedium hair: 1.5 to 2 hours\r\nLong hair: 2 to 3 hours\r\n\r\nThe timing includes:\r\n\r\nHair preparation – 10 minutes\r\nColor application – 30 to 45 minutes\r\nWaiting time for color – 30 to 45 minutes\r\nHair wash and drying – 20 to 30 minutes\r\n\r\nChocolate brown, burgundy, and caramel brown are among the most popular choices because they look stylish and suit many skin tones.', 1500, 'postpaid', 'services/6NT0DH9qAtYIyXtdHpFFhrIQwnbbdY7NCIb6rkwV.jpg', '2026-04-08 05:40:06', '2026-04-08 05:40:06'),
(8, 'Highlights', 'Highlights mean coloring only some sections of the hair instead of the full hair.\r\n\r\nPopular highlight colors for women:\r\n\r\nCaramel highlights\r\nHoney brown highlights\r\nBlonde highlights\r\nAsh brown highlights\r\nBurgundy highlights\r\nCopper highlights\r\nGolden highlights\r\nRed highlights\r\nFace-framing highlights\r\nBalayage highlights\r\n\r\nTypical salon timing:\r\n\r\nPartial highlights: 1 to 2 hours\r\nFull highlights: 2 to 4 hours\r\nBalayage highlights: 3 to 5 hours\r\n\r\nThe timing usually includes:\r\n\r\nSectioning hair – 10 to 15 minutes\r\nApplying highlight color – 30 to 60 minutes\r\nWaiting time – 30 to 45 minutes\r\nHair wash and styling – 20 to 30 minutes\r\n\r\nCaramel, honey brown, and burgundy highlights are very popular because they look stylish and suit dark hair well.', 1000, 'postpaid', 'services/qlLlMdbS5dp69ZTGDwyQCLtonUu3HoOgyFw9D8S8.jpg', '2026-04-08 05:41:00', '2026-04-08 05:41:00'),
(9, 'Hair Wash', 'Hair wash at a salon usually includes shampoo, conditioner, towel drying, and sometimes basic blow drying.\r\n\r\nTypical timing:\r\n\r\nBasic hair wash: 10–15 minutes\r\nHair wash with conditioner: 15–20 minutes\r\nHair wash with blow dry: 20–30 minutes\r\nHair wash with hair spa: 30–60 minutes\r\n\r\nTypical steps:\r\n\r\nWet hair – 2 minutes\r\nShampoo – 3 to 5 minutes\r\nRinse – 2 minutes\r\nConditioner – 3 to 5 minutes\r\nTowel dry or blow dry – 5 to 15 minutes\r\n\r\nHair wash with a head massage is also popular because it feels relaxing and improves blood circulation.', 500, 'postpaid', 'services/s3mVUFP4A8GahriWMRFtzPGx7H6R7mu2CMWAv2IR.jpg', '2026-04-08 05:41:56', '2026-04-08 05:41:56'),
(10, 'Hair spa', 'Hair spa is a deep hair treatment that helps reduce dryness, frizz, dandruff, and hair damage. It also makes hair softer, smoother, and shinier.\r\n\r\nTypical steps:\r\n\r\nHair wash with shampoo – 5 to 10 minutes\r\nApplying hair spa cream or mask – 5 minutes\r\nHair massage – 10 to 15 minutes\r\nSteam treatment – 10 to 15 minutes\r\nHair wash and rinse – 5 to 10 minutes\r\nBlow dry or basic styling – 10 to 15 minutes\r\n\r\nTotal timing:\r\n\r\nBasic hair spa: 30 to 45 minutes\r\nHair spa with deep conditioning and styling: 45 to 60 minutes\r\n\r\nPopular hair spa types:\r\n\r\nAnti-dandruff hair spa\r\nSmoothening hair spa\r\nKeratin hair spa\r\nDeep conditioning spa\r\nHair fall control spa\r\nDry and damaged hair spa\r\n\r\nHair spa is often done once every 2 to 4 weeks for better results.', 2500, 'postpaid', 'services/Hrb2Kws7HcSPLyCApioe5oijYfx3rfUHaEzGt3xg.jpg', '2026-04-08 05:42:52', '2026-04-08 05:42:52');

